31	/* ── URL parsing helper ─────────────────────────────────── */
32	
33	typedef struct {
34	    char host[128];
35	    char port[8];
36	    char path[128];
37	    bool use_tls;
38	} parsed_url_t;
39	
40	static int parse_url(const char* url, parsed_url_t* out)
41	{
42	    memset(out, 0, sizeof(*out));
43	
44	    if (strncmp(url, "https://", 8) == 0) {
45	        out->use_tls = true;
46	        url += 8;
47	        strncpy(out->port, "443", sizeof(out->port) - 1);
48	    } else if (strncmp(url, "http://", 7) == 0) {
49	        out->use_tls = false;
50	        url += 7;
51	        strncpy(out->port, "80", sizeof(out->port) - 1);
52	    } else {
53	        return -1;
54	    }
55	
56	    const char* slash = strchr(url, '/');
57	    const char* colon = strchr(url, ':');
58	
59	    if (colon && (!slash || colon < slash)) {
60	        size_t hlen = colon - url;
61	        if (hlen >= sizeof(out->host))
62	            hlen = sizeof(out->host) - 1;
63	        memcpy(out->host, url, hlen);
64	        out->host[hlen] = '\0';
65	
66	        colon++;
67	        const char* pend = slash ? slash : colon + strlen(colon);
68	        size_t plen = pend - colon;
69	        if (plen >= sizeof(out->port))
70	            plen = sizeof(out->port) - 1;
71	        memcpy(out->port, colon, plen);
72	        out->port[plen] = '\0';
73	    } else {
74	        size_t hlen = slash ? (size_t)(slash - url) : strlen(url);
75	        if (hlen >= sizeof(out->host))
76	            hlen = sizeof(out->host) - 1;
77	        memcpy(out->host, url, hlen);
78	        out->host[hlen] = '\0';
79	    }
80	
81	    if (slash) {
82	        strncpy(out->path, slash, sizeof(out->path) - 1);
83	    } else {
84	        strncpy(out->path, "/", sizeof(out->path) - 1);
85	    }
86	
87	    return 0;
88	}
