121	/* ── JSON-RPC request builder ───────────────────────────── */
122	
123	static char* build_jsonrpc_request(const char* method, cJSON* params)
124	{
125	    cJSON* req = cJSON_CreateObject();
126	    if (!req) {
127	        /* Caller passed params expecting us to take ownership — free it */
128	        cJSON_Delete(params);
129	        return NULL;
130	    }
131	
132	    cJSON_AddStringToObject(req, "jsonrpc", "2.0");
133	    cJSON_AddStringToObject(req, "method", method);
134	    cJSON_AddNumberToObject(req, "id", s_req_id++);
135	
136	    if (params) {
137	        cJSON_AddItemToObject(req, "params", params);
138	    } else {
139	        cJSON_AddItemToObject(req, "params", cJSON_CreateObject());
140	    }
141	
142	    char* json = cJSON_PrintUnformatted(req);
143	    cJSON_Delete(req);
144	    return json;
145	}
