147	/* ── HTTP POST to MCP server ────────────────────────────── */
148	
149	static int mcp_http_post(mcp_remote_server_t* srv, const char* body,
150	    char* resp_buf, size_t resp_cap)
151	{
152	    vela_header_t headers[5];
153	    int h = 0;
154	
155	    headers[h].name = "Accept";
156	    headers[h].value = "application/json, text/event-stream";
157	    h++;
158	
159	    /* Force new connection each request — some MCP servers (e.g. DiDi)
160	     * close the connection after responding, but vela_tls pool tries to
161	     * reuse it and hangs on read. */
162	    headers[h].name = "Connection";
163	    headers[h].value = "close";
164	    h++;
165	
166	    if (srv->session_id[0]) {
167	        headers[h].name = "Mcp-Session";
168	        headers[h].value = srv->session_id;
169	        h++;
170	    }
171	
172	    if (srv->token[0]) {
173	        /* Build "Bearer <token>" — use heap to avoid static buffer race */
174	        char* auth_buf = malloc(192);
175	        if (!auth_buf)
176	            return -1;
177	        snprintf(auth_buf, 192, "Bearer %s", srv->token);
178	        headers[h].name = "Authorization";
179	        headers[h].value = auth_buf;
180	        h++;
181	
182	        headers[h].name = NULL;
183	        headers[h].value = NULL;
184	
185	        int status;
186	        if (srv->parsed.use_tls) {
187	            status = vela_https_post_json(
188	                srv->parsed.host, srv->parsed.port, srv->parsed.path,
189	                headers, body, resp_buf, resp_cap);
190	        } else {
191	            status = vela_http_post_json(
192	                srv->parsed.host, srv->parsed.port, srv->parsed.path,
193	                headers, body, resp_buf, resp_cap);
194	        }
195	
196	        free(auth_buf);
197	        return status;
198	    }
199	
200	    headers[h].name = NULL;
201	    headers[h].value = NULL;
202	
203	    int status;
204	    if (srv->parsed.use_tls) {
205	        status = vela_https_post_json(
206	            srv->parsed.host, srv->parsed.port, srv->parsed.path,
207	            headers, body, resp_buf, resp_cap);
208	    } else {
209	        status = vela_http_post_json(
210	            srv->parsed.host, srv->parsed.port, srv->parsed.path,
211	            headers, body, resp_buf, resp_cap);
212	    }
213	
214	    return status;
215	}
