217	/* ── Parse JSON-RPC response ────────────────────────────── */
218	
219	static cJSON* parse_jsonrpc_result(const char* resp_json)
220	{
221	    cJSON* root = cJSON_Parse(resp_json);
222	    if (!root)
223	        return NULL;
224	
225	    cJSON* error = cJSON_GetObjectItem(root, "error");
226	    if (error) {
227	        cJSON* msg = cJSON_GetObjectItem(error, "message");
228	        syslog(LOG_ERR, "[%s] JSON-RPC error: %s\n", TAG,
229	            (msg && cJSON_IsString(msg)) ? msg->valuestring : "unknown");
230	        cJSON_Delete(root);
231	        return NULL;
232	    }
233	
234	    cJSON* result = cJSON_DetachItemFromObject(root, "result");
235	    cJSON_Delete(root);
236	    return result;
237	}
