239	/* ── MCP initialize handshake (called WITHOUT lock) ─────── */
240	
241	static int mcp_client_handshake(mcp_remote_server_t* srv)
242	{
243	    cJSON* params = cJSON_CreateObject();
244	    if (!params)
245	        return ERROR;
246	
247	    cJSON* caps = cJSON_CreateObject();
248	    if (!caps) {
249	        cJSON_Delete(params);
250	        return ERROR;
251	    }
252	    cJSON_AddItemToObject(params, "capabilities", caps);
253	
254	    cJSON* info = cJSON_CreateObject();
255	    if (!info) {
256	        cJSON_Delete(params);
257	        return ERROR;
258	    }
259	    cJSON_AddStringToObject(info, "name", "agent");
260	    cJSON_AddStringToObject(info, "version", "1.0.0");
261	    cJSON_AddItemToObject(params, "clientInfo", info);
262	
263	    cJSON_AddStringToObject(params, "protocolVersion", "2025-03-26");
264	
265	    char* body = build_jsonrpc_request("initialize", params);
266	    if (!body)
267	        return ERROR;
268	
269	    char* resp_buf = malloc(MCP_RESP_BUF_SIZE);
270	    if (!resp_buf) {
271	        free(body);
272	        return ERROR;
273	    }
274	    resp_buf[0] = '\0';
275	
276	    int status = mcp_http_post(srv, body, resp_buf, MCP_RESP_BUF_SIZE);
277	    free(body);
278	
279	    if (status < 200 || status >= 300) {
280	        syslog(LOG_ERR, "[%s] %s initialize failed: HTTP %d\n",
281	            TAG, srv->name, status);
282	        free(resp_buf);
283	        return ERROR;
284	    }
285	
286	    cJSON* result = parse_jsonrpc_result(resp_buf);
287	    free(resp_buf);
288	
289	    if (!result) {
290	        syslog(LOG_ERR, "[%s] %s initialize: bad response\n", TAG, srv->name);
291	        return ERROR;
292	    }
293	
294	    /* FIX #5: validate protocolVersion in response */
295	    cJSON* proto = cJSON_GetObjectItem(result, "protocolVersion");
296	    if (!proto || !cJSON_IsString(proto)) {
297	        syslog(LOG_ERR, "[%s] %s: missing protocolVersion in init response\n",
298	            TAG, srv->name);
299	        cJSON_Delete(result);
300	        return ERROR;
301	    }
302	
303	    /* Accept any 2025-xx-xx version for forward compat */
304	    if (strncmp(proto->valuestring, "2025-", 5) != 0
305	        && strncmp(proto->valuestring, "2024-", 5) != 0) {
306	        syslog(LOG_ERR, "[%s] %s: unsupported protocol: %s\n",
307	            TAG, srv->name, proto->valuestring);
308	        cJSON_Delete(result);
309	        return ERROR;
310	    }
311	
312	    /* Extract server info for logging */
313	    cJSON* sinfo = cJSON_GetObjectItem(result, "serverInfo");
314	    if (sinfo) {
315	        cJSON* sname = cJSON_GetObjectItem(sinfo, "name");
316	        syslog(LOG_INFO, "[%s] Connected to MCP server: %s (proto %s)\n", TAG,
317	            (sname && cJSON_IsString(sname)) ? sname->valuestring : "unknown",
318	            proto->valuestring);
319	    }
320	
321	    cJSON_Delete(result);
322	
323	    /* MCP spec says client SHOULD send notifications/initialized, but it's
324	     * a notification (no response expected). Some servers (e.g. DiDi) return
325	     * HTTP 202 with empty body, which causes vela_tls to hang waiting for
326	     * response data. Since this notification is optional and no server we
327	     * support requires it, skip it to avoid compatibility issues. */
328	
329	    /* FIX #3: session_id extraction — NOTE: vela_https_post_json does not
330	     * expose response headers. We set a TODO marker. For servers that require
331	     * Mcp-Session (stateful transport), the TLS layer would need to be
332	     * extended to return headers. Most MCP servers (including Amap) work
333	     * without session tracking in stateless mode. */
334	
335	    srv->initialized = true;
336	    syslog(LOG_INFO, "[%s] %s handshake complete\n", TAG, srv->name);
337	    return OK;
338	}
