340	/* ── Discover tools from one server (called WITHOUT lock) ── */
341	
342	static int discover_server_tools(mcp_remote_server_t* srv,
343	    mcp_remote_tool_t* out_tools,
344	    int max_tools)
345	{
346	    if (!srv->initialized) {
347	        if (mcp_client_handshake(srv) != OK)
348	            return -1;
349	    }
350	
351	    char* body = build_jsonrpc_request("tools/list", NULL);
352	    if (!body)
353	        return -1;
354	
355	    char* resp_buf = malloc(MCP_RESP_BUF_SIZE);
356	    if (!resp_buf) {
357	        free(body);
358	        return -1;
359	    }
360	    resp_buf[0] = '\0';
361	
362	    int status = mcp_http_post(srv, body, resp_buf, MCP_RESP_BUF_SIZE);
363	    free(body);
364	
365	    if (status < 200 || status >= 300) {
366	        syslog(LOG_ERR, "[%s] %s tools/list failed: HTTP %d\n",
367	            TAG, srv->name, status);
368	        free(resp_buf);
369	        return -1;
370	    }
371	
372	    cJSON* result = parse_jsonrpc_result(resp_buf);
373	    free(resp_buf);
374	    if (!result)
375	        return -1;
376	
377	    cJSON* tools = cJSON_GetObjectItem(result, "tools");
378	    if (!tools || !cJSON_IsArray(tools)) {
379	        cJSON_Delete(result);
380	        return 0;
381	    }
382	
383	    int added = 0;
384	    cJSON* tool = NULL;
385	    cJSON_ArrayForEach(tool, tools)
386	    {
387	        if (added >= max_tools)
388	            break;
389	
390	        cJSON* name = cJSON_GetObjectItem(tool, "name");
391	        cJSON* desc = cJSON_GetObjectItem(tool, "description");
392	        cJSON* schema = cJSON_GetObjectItem(tool, "inputSchema");
393	
394	        if (!name || !cJSON_IsString(name))
395	            continue;
396	
397	        mcp_remote_tool_t* t = &out_tools[added];
398	        memset(t, 0, sizeof(*t));
399	
400	        /* FIX #6: prefix tool name with "server_name." to avoid collision */
401	        snprintf(t->name, sizeof(t->name), "%s.%s",
402	            srv->name, name->valuestring);
403	        snprintf(t->description, sizeof(t->description), "[%s] %s",
404	            srv->name,
405	            (desc && cJSON_IsString(desc)) ? desc->valuestring : "");
406	        strncpy(t->server_name, srv->name, sizeof(t->server_name) - 1);
407	        t->server_name[sizeof(t->server_name) - 1] = '\0';
408	
409	        if (schema) {
410	            t->input_schema_json = cJSON_PrintUnformatted(schema);
411	        } else {
412	            t->input_schema_json = strdup(
413	                "{\"type\":\"object\",\"properties\":{}}");
414	        }
415	
416	        if (!t->input_schema_json)
417	            continue;
418	
419	        added++;
420	    }
421	
422	    cJSON_Delete(result);
423	    syslog(LOG_INFO, "[%s] %s: discovered %d tools\n", TAG, srv->name, added);
424	    return added;
425	}
