429	int mcp_client_init(void)
430	{
431	    pthread_mutex_lock(&s_mtx);
432	    if (s_inited) {
433	        pthread_mutex_unlock(&s_mtx);
434	        return OK;
435	    }
436	    s_server_count = 0;
437	    s_tool_count = 0;
438	    atomic_store(&s_req_id, 1);
439	    s_inited = true;
440	    pthread_mutex_unlock(&s_mtx);
441	
442	    /* Register as tool provider */
443	    tool_registry_register_provider("mcp_client",
444	                                    mcp_client_get_tools_json,
445	                                    mcp_client_execute);
446	
447	    syslog(LOG_INFO, "[%s] MCP client initialized\n", TAG);
448	    return OK;
449	}
