451	int mcp_client_add_server(const char* name, const char* url,
452	    const char* token)
453	{
454	    if (!name || !url)
455	        return ERROR;
456	
457	    pthread_mutex_lock(&s_mtx);
458	
459	    if (s_server_count >= MCP_CLIENT_MAX_SERVERS) {
460	        syslog(LOG_ERR, "[%s] Max servers reached (%d)\n",
461	            TAG, MCP_CLIENT_MAX_SERVERS);
462	        pthread_mutex_unlock(&s_mtx);
463	        return ERROR;
464	    }
465	
466	    /* Check for duplicate */
467	    for (int i = 0; i < s_server_count; i++) {
468	        if (strcmp(s_servers[i].name, name) == 0) {
469	            syslog(LOG_WARNING, "[%s] Server '%s' already exists\n",
470	                TAG, name);
471	            pthread_mutex_unlock(&s_mtx);
472	            return ERROR;
473	        }
474	    }
475	
476	    mcp_remote_server_t* srv = &s_servers[s_server_count];
477	    memset(srv, 0, sizeof(*srv));
478	    strncpy(srv->name, name, sizeof(srv->name) - 1);
479	    strncpy(srv->url, url, sizeof(srv->url) - 1);
480	    if (token) {
481	        strncpy(srv->token, token, sizeof(srv->token) - 1);
482	    }
483	
484	    if (parse_url(url, &srv->parsed) != 0) {
485	        syslog(LOG_ERR, "[%s] Invalid URL: %s\n", TAG, url);
486	        pthread_mutex_unlock(&s_mtx);
487	        return ERROR;
488	    }
489	
490	    s_server_count++;
491	    syslog(LOG_INFO, "[%s] Added server '%s' -> %s\n", TAG, name, url);
492	    pthread_mutex_unlock(&s_mtx);
493	    return OK;
494	}
