496	int mcp_client_remove_server(const char* name)
497	{
498	    if (!name)
499	        return ERROR;
500	
501	    pthread_mutex_lock(&s_mtx);
502	
503	    int idx = -1;
504	    for (int i = 0; i < s_server_count; i++) {
505	        if (strcmp(s_servers[i].name, name) == 0) {
506	            idx = i;
507	            break;
508	        }
509	    }
510	
511	    if (idx < 0) {
512	        pthread_mutex_unlock(&s_mtx);
513	        return ERROR;
514	    }
515	
516	    /* Remove tools belonging to this server */
517	    int w = 0;
518	    for (int r = 0; r < s_tool_count; r++) {
519	        if (strcmp(s_tools[r].server_name, name) != 0) {
520	            if (w != r)
521	                s_tools[w] = s_tools[r];
522	            w++;
523	        } else {
524	            free(s_tools[r].input_schema_json);
525	            s_tools[r].input_schema_json = NULL;
526	        }
527	    }
528	    s_tool_count = w;
529	
530	    /* Shift servers array */
531	    if (idx < s_server_count - 1) {
532	        memmove(&s_servers[idx], &s_servers[idx + 1],
533	            (s_server_count - idx - 1) * sizeof(mcp_remote_server_t));
534	    }
535	    s_server_count--;
536	
537	    pthread_mutex_unlock(&s_mtx);
538	    syslog(LOG_INFO, "[%s] Removed server '%s'\n", TAG, name);
539	    return OK;
540	}
