542	/* FIX #1: discover — lock only protects data copy, network calls outside lock */
543	
544	int mcp_client_discover(void)
545	{
546	    /* Step 1: lock, copy server list, clear old tools */
547	    pthread_mutex_lock(&s_mtx);
548	
549	    int nservers = s_server_count;
550	    if (nservers == 0) {
551	        pthread_mutex_unlock(&s_mtx);
552	        return 0;
553	    }
554	
555	    /* Stack-copy server structs so we can release the lock */
556	    mcp_remote_server_t* srv_copy = malloc(
557	        nservers * sizeof(mcp_remote_server_t));
558	    if (!srv_copy) {
559	        pthread_mutex_unlock(&s_mtx);
560	        return -1;
561	    }
562	    memcpy(srv_copy, s_servers, nservers * sizeof(mcp_remote_server_t));
563	
564	    /* Clear existing tools */
565	    for (int i = 0; i < s_tool_count; i++) {
566	        free(s_tools[i].input_schema_json);
567	        s_tools[i].input_schema_json = NULL;
568	    }
569	    s_tool_count = 0;
570	
571	    pthread_mutex_unlock(&s_mtx);
572	
573	    /* Step 2: network calls WITHOUT lock — each server gets its own
574	     * temporary tool buffer to avoid blocking other operations */
575	    mcp_remote_tool_t* tmp_tools = malloc(
576	        MCP_CLIENT_MAX_TOOLS * sizeof(mcp_remote_tool_t));
577	    if (!tmp_tools) {
578	        free(srv_copy);
579	        return -1;
580	    }
581	
582	    int total = 0;
583	    for (int i = 0; i < nservers; i++) {
584	        int remaining = MCP_CLIENT_MAX_TOOLS - total;
585	        if (remaining <= 0)
586	            break;
587	
588	        int n = discover_server_tools(&srv_copy[i],
589	            &tmp_tools[total], remaining);
590	        if (n > 0)
591	            total += n;
592	
593	        /* Sync initialized/session_id back under lock */
594	        pthread_mutex_lock(&s_mtx);
595	        for (int j = 0; j < s_server_count; j++) {
596	            if (strcmp(s_servers[j].name, srv_copy[i].name) == 0) {
597	                s_servers[j].initialized = srv_copy[i].initialized;
598	                memcpy(s_servers[j].session_id, srv_copy[i].session_id,
599	                    sizeof(s_servers[j].session_id));
600	                break;
601	            }
602	        }
603	        pthread_mutex_unlock(&s_mtx);
604	    }
605	
606	    /* Step 3: lock, merge discovered tools into global array */
607	    pthread_mutex_lock(&s_mtx);
608	
609	    for (int i = 0; i < total && s_tool_count < MCP_CLIENT_MAX_TOOLS; i++) {
610	        s_tools[s_tool_count] = tmp_tools[i];
611	        /* Ownership of input_schema_json transferred, don't free */
612	        s_tool_count++;
613	    }
614	
615	    /* Free any tools that didn't fit */
616	    for (int i = s_tool_count; i < total; i++) {
617	        free(tmp_tools[i].input_schema_json);
618	        tmp_tools[i].input_schema_json = NULL;
619	    }
620	
621	    pthread_mutex_unlock(&s_mtx);
622	
623	    free(tmp_tools);
624	    free(srv_copy);
625	    syslog(LOG_INFO, "[%s] Total remote tools: %d\n", TAG, total);
626	    return total;
627	}
