637	    /* Step 1: lock, find tool + server, copy what we need, unlock */
638	    pthread_mutex_lock(&s_mtx);
639	
640	    const char* srv_name = NULL;
641	    /* FIX #6: tool names are now prefixed "server.tool", but also try
642	     * unprefixed match for backward compat with tool_registry fallback */
643	    for (int i = 0; i < s_tool_count; i++) {
644	        if (strcmp(s_tools[i].name, name) == 0) {
645	            srv_name = s_tools[i].server_name;
646	            break;
647	        }
648	    }
649	
650	    if (!srv_name) {
651	        pthread_mutex_unlock(&s_mtx);
652	        return ERROR;
653	    }
654	
655	    /* Copy server struct so we can release lock before network call */
656	    mcp_remote_server_t srv_local;
657	    bool found = false;
658	    for (int i = 0; i < s_server_count; i++) {
659	        if (strcmp(s_servers[i].name, srv_name) == 0) {
660	            srv_local = s_servers[i];
661	            found = true;
662	            break;
663	        }
664	    }
665	
666	    pthread_mutex_unlock(&s_mtx);
667	
668	    if (!found)
669	        return ERROR;
670	
671	    /* Step 2: build request and do network call WITHOUT lock */
672	
673	    /* Extract the original tool name (strip server prefix for remote call) */
674	    const char* dot = strchr(name, '.');
675	    const char* remote_name = dot ? dot + 1 : name;
676	
677	    cJSON* params = cJSON_CreateObject();
678	    if (!params)
679	        return ERROR;
680	
681	    cJSON_AddStringToObject(params, "name", remote_name);
682	    cJSON* args = cJSON_Parse(input_json ? input_json : "{}");
683	    if (!args) {
684	        args = cJSON_CreateObject();
685	        if (!args) {
686	            cJSON_Delete(params);
687	            return ERROR;
688	        }
689	    }
690	    cJSON_AddItemToObject(params, "arguments", args);
691	
692	    /* build_jsonrpc_request takes ownership of params (frees on failure) */
693	    char* body = build_jsonrpc_request("tools/call", params);
694	    if (!body)
695	        return ERROR;
696	
697	    char* resp_buf = malloc(MCP_RESP_BUF_SIZE);
698	    if (!resp_buf) {
699	        free(body);
700	        return ERROR;
701	    }
702	    resp_buf[0] = '\0';
703	
704	    int status = mcp_http_post(&srv_local, body, resp_buf, MCP_RESP_BUF_SIZE);
705	    free(body);
706	
707	    if (status < 200 || status >= 300) {
708	        snprintf(output, output_size,
709	            "{\"error\":\"MCP remote call failed: HTTP %d\"}", status);
710	        free(resp_buf);
711	        return ERROR;
712	    }
713	
714	    /* Parse result -> content[0] -> text */
715	    cJSON* result = parse_jsonrpc_result(resp_buf);
716	    free(resp_buf);
717	
718	    if (!result) {
719	        snprintf(output, output_size,
720	            "{\"error\":\"MCP remote: bad response\"}");
721	        return ERROR;
722	    }
723	
724	    cJSON* content = cJSON_GetObjectItem(result, "content");
725	    if (content && cJSON_IsArray(content)) {
726	        cJSON* first = cJSON_GetArrayItem(content, 0);
727	        if (first) {
728	            cJSON* text = cJSON_GetObjectItem(first, "text");
729	            if (text && cJSON_IsString(text)) {
730	                strncpy(output, text->valuestring, output_size - 1);
731	                output[output_size - 1] = '\0';
732	                cJSON_Delete(result);
733	                return OK;
734	            }
735	        }
736	    }
737	
738	    /* Fallback: stringify the whole result */
739	    char* fallback = cJSON_PrintUnformatted(result);
740	    if (fallback) {
741	        strncpy(output, fallback, output_size - 1);
742	        output[output_size - 1] = '\0';
743	        free(fallback);
744	    }
745	
746	    cJSON_Delete(result);
747	    return OK;
748	}
